if(title&&caption){const label=title.querySelector('b');if(label)label.textContent='时间范围';caption.hidden=true;const controls=document.createElement('div');controls.className='date-controls';controls.innerHTML='<button id="date-prev20" type="button" aria-label="前一交易日">‹</button><strong id="date-display20" class="date-display"></strong><button id="date-next20" type="button" aria-label="后一交易日">›</button>';title.appendChild(controls);const display=document.getElementById('date-display20'),prev=document.getElementById('date-prev20'),next=document.getElementById('date-next20'),iso=s=>`${s.slice(0,4)}-${s.slice(4,6)}-${s.slice(6,8)}`;function sync(){display.textContent=iso(DATA.dates[endIndex]);prev.disabled=endIndex<=90;next.disabled=endIndex>=DATA.dates.length-1}function move(index){const target=Math.max(90,Math.min(DATA.dates.length-1,index));slider.value=target;slider.dispatchEvent(new Event('input',{bubbles:true}));sync()}function bindHold(button,delta){let delay=null,repeat=null;const step=()=>move(endIndex+delta),stop=()=>{if(delay)clearTimeout(delay);if(repeat)clearInterval(repeat);delay=repeat=null};button.onpointerdown=e=>{e.preventDefault();stop();step();try{button.setPointerCapture(e.pointerId)}catch(_){}delay=setTimeout(()=>{repeat=setInterval(step,75)},360)};button.onpointerup=stop;button.onpointercancel=stop;button.onpointerleave=stop;button.onclick=e=>e.preventDefault();button.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();step()}}}bindHold(prev,-1);bindHold(next,1);new MutationObserver(sync).observe(caption,{childList:true,subtree:true,characterData:true});sync();const historyEnd=document.getElementById('history-end');if(historyEnd)historyEnd.textContent='最新'}
