const plot=document.getElementById('plot');function verticalText(x,y,a,b,color){return`<text x="${x}" y="${y}" fill="${color}" font-size="10" font-weight="800" text-anchor="middle"><tspan x="${x}" dy="0">${a}</tspan><tspan x="${x}" dy="13">${b}</tspan></text>`}function semanticLayer(){if(!plot||plot.querySelector('#semantic-axis22'))return;[...plot.querySelectorAll('text')].forEach(node=>{if(node.textContent==='累计相对向上迁移'||node.textContent==='累计相对向下迁移')node.remove()});const ns='http://www.w3.org/2000/svg',g=document.createElementNS(ns,'g');g.id='semantic-axis22';g.setAttribute('opacity','.84');g.innerHTML=`<defs><linearGradient id="arrow-up23" gradientUnits="userSpaceOnUse" x1="0" y1="480" x2="0" y2="53"><stop offset="0" stop-color="#5f8b84"/><stop offset=".48" stop-color="#80958a"/><stop offset="1" stop-color="#d64b45"/></linearGradient><linearGradient id="arrow-down23" gradientUnits="userSpaceOnUse" x1="0" y1="58" x2="0" y2="487"><stop offset="0" stop-color="#d64b45"/><stop offset=".52" stop-color="#80958a"/><stop offset="1" stop-color="#5f8b84"/></linearGradient></defs><path d="M30 480 L30 53 L22 63" fill="none" stroke="url(#arrow-up23)" stroke-width="1.45" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>${verticalText(16,160,'进','攻','#b84f49')}${verticalText(16,358,'修','复','#4f7f79')}<path d="M39 58 L39 487 L47 477" fill="none" stroke="url(#arrow-down23)" stroke-width="1.45" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>${verticalText(53,160,'回','落','#b84f49')}${verticalText(53,358,'走','弱','#4f7f79')}`;plot.appendChild(g)}if(plot){new MutationObserver(semanticLayer).observe(plot,{childList:true});semanticLayer()}
