(()=>{
 const svg=document.getElementById('plot'),pane=svg?.closest('.chart-pane');
 if(!svg||!pane)return;
 const tip=document.createElement('div');
 tip.className='contribution-html-tooltip';tip.hidden=true;tip.setAttribute('role','tooltip');
 pane.appendChild(tip);
 let pointer=null,frame=0;
 const escapeHTML=value=>String(value??'').replace(/[&<>\"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[ch]));
 function place(){
   if(!pointer||tip.hidden)return;
   const rect=pane.getBoundingClientRect(),gap=12,edge=8,w=tip.offsetWidth,h=tip.offsetHeight;
   let x=pointer.x-rect.left+gap,y=pointer.y-rect.top+gap;
   if(x+w>rect.width-edge)x=pointer.x-rect.left-w-gap;
   if(y+h>rect.height-edge)y=pointer.y-rect.top-h-gap;
   tip.style.left=Math.max(edge,Math.min(rect.width-w-edge,x))+'px';
   tip.style.top=Math.max(edge,Math.min(rect.height-h-edge,y))+'px';
 }
 function sync(){
   frame=0;
   const probe=svg.querySelector('#probe-values28');
   if(!pointer||!probe){tip.hidden=true;return;}
   const texts=[...probe.querySelectorAll('text')].map(node=>node.textContent||'');
   if(!texts.length){tip.hidden=true;return;}
   const dots=[...probe.querySelectorAll('circle')].map(node=>node.getAttribute('fill')||'#64748b');
   const rows=[];
   for(let i=1,row=0;i+1<texts.length;i+=2,row++)rows.push(`<div class="contribution-tooltip-row"><span class="contribution-tooltip-dot" style="background:${escapeHTML(dots[row]||'#64748b')}"></span><span>${escapeHTML(texts[i])}</span><span class="contribution-tooltip-value">${escapeHTML(texts[i+1])}</span></div>`);
   tip.innerHTML=`<div class="contribution-tooltip-date">${escapeHTML(texts[0])}</div>${rows.join('')}`;
   tip.hidden=false;place();
 }
 function schedule(){if(!frame)frame=requestAnimationFrame(sync)}
 svg.addEventListener('pointermove',event=>{pointer={x:event.clientX,y:event.clientY};schedule()});
 svg.addEventListener('pointerleave',()=>{pointer=null;tip.hidden=true});
 new MutationObserver(schedule).observe(svg,{childList:true,subtree:true});
 window.addEventListener('resize',place);
})();


