(()=>{
const list=document.getElementById('rank-list');if(!list)return;
let manifest=null,drawer=null,scrim=null,requestToken=0;const documents=new Map();
const currentDate=()=>((document.getElementById('date-display20')?.textContent)||'').replaceAll('-','');
const activePeriod=()=>document.querySelector('[data-period].active')?.dataset.period||null;
function close(){requestToken+=1;if(drawer)drawer.hidden=true;if(scrim)scrim.hidden=true}
function setup(){if(drawer)return;scrim=document.createElement('div');scrim.className='stock-detail-scrim';scrim.hidden=true;drawer=document.createElement('aside');drawer.className='stock-detail-drawer';drawer.hidden=true;drawer.setAttribute('aria-label','行业个股排行');drawer.innerHTML='<header><div><small>行业个股排行</small><b data-title>成分强弱</b><span data-meta></span></div><button class="stock-detail-close" type="button" aria-label="关闭个股排行">×</button></header><p class="stock-detail-contract">主买净额为个股 L2 主动买卖净额（moneyflow.net_mf_amount），不等同主力净额。</p><div class="stock-detail-tabs" role="tablist" aria-label="个股排行指标"><button data-metric="pct_change">涨跌幅</button><button data-metric="main_net_amount">主力净额</button><button data-metric="active_buy_net_amount">主买净额</button></div><div class="stock-detail-directions" role="tablist" aria-label="个股排行方向"><button data-direction="top">前 5</button><button data-direction="bottom">后 5</button></div><div class="stock-detail-body"></div>';document.body.append(scrim,drawer);scrim.onclick=close;drawer.querySelector('.stock-detail-close').onclick=close;drawer.querySelector('.stock-detail-tabs').onclick=e=>{const button=e.target.closest('[data-metric]');if(button&&drawer._context){drawer._context.metric=button.dataset.metric;render()}};drawer.querySelector('.stock-detail-directions').onclick=e=>{const button=e.target.closest('[data-direction]');if(button&&drawer._context){drawer._context.direction=button.dataset.direction;render()}};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&drawer&&!drawer.hidden)close()})}
function status(message){const body=drawer.querySelector('.stock-detail-body');body.className='stock-detail-body is-status';body.textContent=message}
function render(){const context=drawer._context;if(!context||!context.slot)return;const metric=context.slot.metrics?.[context.metric];drawer.querySelectorAll('[data-metric]').forEach(button=>button.classList.toggle('active',button.dataset.metric===context.metric));drawer.querySelectorAll('[data-direction]').forEach(button=>button.classList.toggle('active',button.dataset.direction===context.direction));if(!metric||metric.status!=='available'){status('有效样本不足 10，当前指标不可用。');return}const body=drawer.querySelector('.stock-detail-body');body.className='stock-detail-body';body.replaceChildren();const rows=metric[context.direction]||[];rows.forEach((row,index)=>{const item=document.createElement('div');item.className='stock-detail-row';const rank=document.createElement('span');rank.className='stock-detail-rank';rank.textContent=String(index+1);const stock=document.createElement('span');stock.className='stock-detail-stock';const name=document.createElement('strong');name.textContent=row.stock_name||'—';const code=document.createElement('small');code.textContent=row.stock_code;stock.append(name,code);const value=document.createElement('b');value.className='stock-detail-value';value.textContent=(row.value>=0?'+':'')+Number(row.value).toFixed(2)+(context.metric==='pct_change'?'%':' 亿');item.append(rank,stock,value);body.append(item)})}
async function open(row){setup();const code=row.dataset.code,name=row.querySelector('.name')?.textContent?.trim()||code,windowValue=activePeriod();scrim.hidden=false;drawer.hidden=false;drawer.querySelector('[data-title]').textContent=name;drawer.querySelector('[data-meta]').textContent=currentDate().replace(/^(\d{4})(\d{2})(\d{2})$/,'$1.$2.$3')+(windowValue?' · '+windowValue+' 日':'');drawer._context={code,metric:'pct_change',direction:row.querySelector('.direction-value')?.classList.contains('negative')?'bottom':'top',slot:null};drawer.querySelectorAll('[data-metric],[data-direction]').forEach(button=>button.classList.remove('active'));drawer.querySelector('.stock-detail-close').focus();if(!windowValue){status('自定义框选区间不支持个股详情，请先选择 1 / 3 / 5 / 10 / 90 日窗口。');return}status('正在读取该行业的个股排行…');const token=++requestToken;try{if(!manifest){const response=await fetch('../sector_rankings/manifest.json');if(!response.ok)throw new Error('manifest');manifest=await response.json()}const ref=manifest.systems?.macro?.current?.sectors?.[code];if(!ref?.path)throw new Error('reference');let document=documents.get(code);if(!document){const response=await fetch('../'+ref.path);if(!response.ok)throw new Error('detail');document=await response.json();if(document.system!=='macro'||document.sector_code!==code||!document.entries)throw new Error('identity');documents.set(code,document)}if(token!==requestToken||drawer.hidden)return;const slot=document.entries?.[currentDate()]?.[String(windowValue)];if(!slot){status('该日期或窗口的个股排行暂不可用。');return}drawer._context.slot=slot;render()}catch(_){if(token===requestToken)status('个股排行加载失败，宏观主数据不受影响。')}}
function attach(){list.querySelectorAll('.rank-row:not([data-stock-detail])').forEach(row=>{row.dataset.stockDetail='1';const target=row.querySelector('.name-wrap')||row;const button=document.createElement('button');button.className='stock-detail-open';button.type='button';button.textContent='个股';button.setAttribute('aria-label','查看该行业个股排行');button.onclick=e=>{e.stopPropagation();open(row)};button.ondblclick=e=>e.stopPropagation();target.append(button)})}
new MutationObserver(attach).observe(list,{childList:true});attach();
})();
